                'Afarerin Xiamenin tehdas osoitti erillisen tuotantolinjan Al Nabighan tilaukselle. Jokainen lauta ladottiin käsin räätälöidyllä PVC:llä värissä ”Arabian Teal” — räätälöity Pantone-väri (PMS 7712 C), joka sovitettiin saaren syvempien riuttavyöhykkeiden mukaan. Kultalehtikohopainanta: 0,5 mikronin 24 karaatin kulta vaakunan ympärillä, suojattuna 3 kerroksella meritason UV-kovettuvaa epoksia. Afarer hankki hiljaiset sähköpumput (JOBE Aero, muunnetut äänenvaimentimilla 38 dB:iin — hiljaisempi kuin saaren ympäröiva aalloikko). Jokaisen pumpun virtajohto punottiin kermaanvärisestä kankaasta huvilasisustukseen sopivaksi. 20 melan setti: räätälöidyt hiilikuituvarret mattakermaassa 24 karaatin kultakaistalla liitoskohdassa ja lavat käsin maalattu koralliriutan motiiveilla xiamenilaisen meritaiteilijan Liao Fangin toimesta. Kosteudensäädetty säilytyskaappi rakennettiin Afarerin puuseppäkumppanin toimesta Milanossa, toimitettiin tasapakkauksessa ja koottiin saarella.',
