                'Tammikuusta huhtikuuhun 2025 Tran työskenteli Afarerin meriteollisuusdivisioonan kanssa suunnitellakseen RescuePro 12\'6" XR:n. Laudassa on 34 tuuman leveys matalan nopeuden vakautta varten, 6 tuuman paksuinen sotilasluokan PVC (1 200 denieriä, testattu 25 PSI:hen) ja tasainen kansi ilman rockeria yhtenäistä välinekiinnitystä varten. Afarer integroi 12 ruostumatonta teräksistä D-rengasta keula-peräkonfiguraatiossa bungee-kiinnitteisiä lääkepodeja (ensiapu, AED, happi) varten. Laudassa on neonkeltainen näkyvyysraita SOLAS-luokan heijastinnauhalla ja keulaan asennettu vetoklyystri, joka on testattu 400 kg:n linjavetoon. 14 päivän aaltoaskeltestauksen jälkeen University of Queenslandissa lopullinen muotoilu hyväksyttiin 7,5 solmun huippunopeudella lastattuna (110 kg:n meloja ja 30 kg:n varusteet).',
