                'Elokuussa 2025 (kesää edeltävä koulutusjakso) Afarerin pelastuskoulutusdivisioona toteutti 40 tunnin ”SUP Rescue Operator” -sertifioinnin 82 vanhemmalle hengenpelastajalle 5 alueellisessa keskuksessa. Kurssi kattoi melontapohjaisen tahdottomien pelastettavien vetämisen (100 m veto alle 3 minuutissa), aaltoalueelle saapumisen ja sieltä poistumisen tekniikat välineiden kanssa, AED:n käytön epävakaalla alustalla ja laudalla tehtävän selkärankaimmobilisaation (ortopediset kaulukset asetettiin laudan vakautta ylläpitäen). Jokainen ehdokas läpäisi käytännökokeen, jossa vaadittiin 200 m:n melominen pelastettavan luo, simuloitu tajuttoman pelastus välineiden noutamisineen ja paluu rantaan — kaikki 7 minuutin sisällä. Läpäisyprosentti oli 89 % (73/82). Läpäisemättömät siirrettiin toissijaisiin rooleihin.',
